insert into public.projects (slug,title_en,title_ar,country,sector,kva,summary_en,summary_ar,images,is_published) values ($q$logistics-warehouse-standby-sharjah$q$,$q$Standby power package for a logistics warehouse$q$,$q$حزمة طاقة احتياطية لمستودع لوجستي$q$,$q$uae$q$,$q$industrial$q$,500,$q$500 kVA Perkins canopy set with a 800 A 4-pole ATS panel and 24-hour base tank, sized for racking lights, dock levellers and cold-room compressors.$q$,$q$مولد بيركنز 500 ك.ف.أ بكابينة عازلة مع لوحة ATS بسعة 800 أمبير 4 أقطاب وخزان يكفي 24 ساعة، لتغذية الإنارة وأبواب التحميل وضواغط غرف التبريد.$q$,array[$q$/images/projects/warehouse.svg$q$]::text[],true) on conflict (slug) do nothing;
insert into public.projects (slug,title_en,title_ar,country,sector,kva,summary_en,summary_ar,images,is_published) values ($q$residential-tower-backup-dubai$q$,$q$Life-safety backup for a residential tower$q$,$q$طاقة احتياطية لأنظمة السلامة في برج سكني$q$,$q$uae$q$,$q$residential$q$,750,$q$750 kVA Cummins set feeding fire pumps, lifts and stair pressurisation through an ACB changeover panel, with remote monitoring for the facility team.$q$,$q$مولد كمنز 750 ك.ف.أ يغذي مضخات الحريق والمصاعد وضغط السلالم عبر لوحة تحويل بقواطع ACB، مع مراقبة عن بُعد لفريق إدارة المبنى.$q$,array[$q$/images/projects/tower.svg$q$]::text[],true) on conflict (slug) do nothing;
insert into public.projects (slug,title_en,title_ar,country,sector,kva,summary_en,summary_ar,images,is_published) values ($q$construction-site-prime-power-riyadh$q$,$q$Prime power for a construction site$q$,$q$طاقة أساسية لموقع إنشاءات$q$,$q$saudi-arabia$q$,$q$construction$q$,400,$q$Two 200 kVA sets with a synchronising panel so one unit can be serviced while the other keeps tower cranes and site offices running.$q$,$q$مولدان بقدرة 200 ك.ف.أ مع لوحة تزامن، بحيث يمكن صيانة أحدهما بينما يواصل الآخر تشغيل الرافعات البرجية ومكاتب الموقع.$q$,array[$q$/images/projects/construction.svg$q$]::text[],true) on conflict (slug) do nothing;
insert into public.projects (slug,title_en,title_ar,country,sector,kva,summary_en,summary_ar,images,is_published) values ($q$clinic-standby-jeddah$q$,$q$Silent standby set for a medical clinic$q$,$q$مولد احتياطي صامت لعيادة طبية$q$,$q$saudi-arabia$q$,$q$healthcare$q$,100,$q$100 kVA super-silent Perkins set with a 200 A ATS panel, transfer time under 10 seconds for imaging and refrigeration loads.$q$,$q$مولد بيركنز صامت جداً 100 ك.ف.أ مع لوحة ATS بسعة 200 أمبير وزمن تحويل أقل من 10 ثوانٍ لأجهزة الأشعة والتبريد.$q$,array[$q$/images/projects/clinic.svg$q$]::text[],true) on conflict (slug) do nothing;
insert into public.projects (slug,title_en,title_ar,country,sector,kva,summary_en,summary_ar,images,is_published) values ($q$factory-power-plant-baghdad$q$,$q$Multi-generator plant for a factory$q$,$q$محطة مولدات متعددة لمصنع$q$,$q$iraq$q$,$q$industrial$q$,2000,$q$Four 500 kVA containerised sets synchronised on a common bus with load-demand control — sized for long daily grid outages.$q$,$q$أربعة مولدات 500 ك.ف.أ داخل حاويات متزامنة على قضيب مشترك مع تحكم حسب الطلب، مصممة لساعات انقطاع الشبكة اليومية الطويلة.$q$,array[$q$/images/projects/factory.svg$q$]::text[],true) on conflict (slug) do nothing;
insert into public.projects (slug,title_en,title_ar,country,sector,kva,summary_en,summary_ar,images,is_published) values ($q$hotel-backup-erbil$q$,$q$Hotel backup power with MDB upgrade$q$,$q$طاقة احتياطية لفندق مع تحديث لوحة التوزيع$q$,$q$iraq$q$,$q$hospitality$q$,630,$q$630 kVA Volvo Penta set, ATS and a new 1600 A main distribution board to separate essential and non-essential loads.$q$,$q$مولد فولفو بنتا 630 ك.ف.أ مع لوحة ATS ولوحة توزيع رئيسية جديدة 1600 أمبير لفصل الأحمال الأساسية عن غير الأساسية.$q$,array[$q$/images/projects/hotel.svg$q$]::text[],true) on conflict (slug) do nothing;
insert into public.projects (slug,title_en,title_ar,country,sector,kva,summary_en,summary_ar,images,is_published) values ($q$telecom-sites-doha$q$,$q$Hybrid power for telecom shelters$q$,$q$طاقة هجينة لمحطات الاتصالات$q$,$q$qatar$q$,$q$telecom$q$,30,$q$30 kVA hybrid generator + battery units that cut engine run-hours on low-load telecom shelters.$q$,$q$وحدات هجينة 30 ك.ف.أ (مولد + بطاريات) تقلل ساعات تشغيل المحرك في محطات الاتصالات منخفضة الحمل.$q$,array[$q$/images/projects/telecom.svg$q$]::text[],true) on conflict (slug) do nothing;
insert into public.projects (slug,title_en,title_ar,country,sector,kva,summary_en,summary_ar,images,is_published) values ($q$farm-solar-hybrid-kenya$q$,$q$Solar-hybrid system for an agricultural estate$q$,$q$نظام شمسي هجين لمزرعة$q$,$q$kenya$q$,$q$commercial$q$,60,$q$PV, battery storage and a 60 kVA diesel backup powering irrigation pumps and cold storage off-grid.$q$,$q$ألواح شمسية وبطاريات مع مولد ديزل احتياطي 60 ك.ف.أ لتشغيل مضخات الري والتخزين المبرد بعيداً عن الشبكة.$q$,array[$q$/images/projects/farm.svg$q$]::text[],true) on conflict (slug) do nothing;
insert into public.projects (slug,title_en,title_ar,country,sector,kva,summary_en,summary_ar,images,is_published) values ($q$mine-site-prime-south-africa$q$,$q$Prime power for a remote mining camp$q$,$q$طاقة أساسية لمخيم تعدين نائٍ$q$,$q$south-africa$q$,$q$oil_gas$q$,1250,$q$1250 kVA Cummins containerised set with bulk fuel tank and remote telemetry for load-shedding-proof camp power.$q$,$q$مولد كمنز 1250 ك.ف.أ داخل حاوية مع خزان وقود كبير ومراقبة عن بُعد لتأمين كهرباء المخيم أثناء فترات تخفيف الأحمال.$q$,array[$q$/images/projects/mine.svg$q$]::text[],true) on conflict (slug) do nothing;
insert into public.testimonials (client_name,client_company,country,quote_en,quote_ar,rating,is_published) select $q$Operations Manager$q$,$q$Logistics company, Sharjah$q$,$q$uae$q$,$q$They sized the generator and ATS together and delivered from SAIF Zone within days. The WhatsApp updates meant we always knew where the order stood.$q$,$q$قاموا باختيار المولد ولوحة ATS معاً وسلّموا من المنطقة الحرة خلال أيام، ومتابعة الواتساب جعلتنا نعرف حالة الطلب دائماً.$q$,5,false where not exists (select 1 from public.testimonials where quote_en = $q$They sized the generator and ATS together and delivered from SAIF Zone within days. The WhatsApp updates meant we always knew where the order stood.$q$);
insert into public.testimonials (client_name,client_company,country,quote_en,quote_ar,rating,is_published) select $q$Project Engineer$q$,$q$Contractor, Riyadh$q$,$q$saudi-arabia$q$,$q$Clear datasheets, realistic lead times and a synchronising panel that worked first time on site.$q$,$q$مواصفات واضحة ومواعيد تسليم واقعية ولوحة تزامن عملت من أول تشغيل في الموقع.$q$,5,false where not exists (select 1 from public.testimonials where quote_en = $q$Clear datasheets, realistic lead times and a synchronising panel that worked first time on site.$q$);
insert into public.testimonials (client_name,client_company,country,quote_en,quote_ar,rating,is_published) select $q$Procurement Lead$q$,$q$Manufacturer, Baghdad$q$,$q$iraq$q$,$q$Export paperwork to Iraq was handled end-to-end. The sets arrived tested and ready for commissioning.$q$,$q$تم التعامل مع أوراق التصدير إلى العراق بالكامل، ووصلت المولدات مختبرة وجاهزة للتشغيل.$q$,5,false where not exists (select 1 from public.testimonials where quote_en = $q$Export paperwork to Iraq was handled end-to-end. The sets arrived tested and ready for commissioning.$q$);
